import{c as i,$ as a,Q as o,j as n,g as l,o as s,aw as h,n as t,m as c}from"./chunks/framework.CHJbb1iY.js";const k=JSON.parse('{"title":"Github 使用技巧","description":"","frontmatter":{"sidebar":false,"aside":"left","outline":[2,3]},"headers":[],"relativePath":"docs/笔记/Github/Github使用指南.md","filePath":"docs/笔记/Github/Github使用指南.md"}'),d={name:"docs/笔记/Github/Github使用指南.md"},u={id:"github-使用技巧",tabindex:"-1"};function p(g,e,b,f,_,m){const r=a("center");return o(),n("div",null,[l("h1",u,[s(r,null,{default:h(()=>[...e[0]||(e[0]=[t("Github 使用技巧",-1)])]),_:1}),e[1]||(e[1]=t()),e[2]||(e[2]=l("a",{class:"header-anchor",href:"#github-使用技巧","aria-label":'Permalink to "<center>Github 使用技巧</center>"'},"​",-1))]),e[3]||(e[3]=c('<hr><h2 id="一、常见名词" tabindex="-1">一、常见名词 <a class="header-anchor" href="#一、常见名词" aria-label="Permalink to &quot;一、常见名词&quot;">​</a></h2><ul><li><strong>repository</strong>：仓库</li><li><strong>fork</strong>：复刻</li><li><strong>star</strong>：收藏</li><li><strong>codespaces</strong>：在线代码空间</li><li><strong>issue</strong>：在一个仓库创建话题讨论，可以由仓库主人选择开始和结束话题的讨论</li><li><strong>pull request（也称 pr）</strong>：协同其他仓库开发，请求仓库主人拉取自己的代码合并到仓库的主分支，创建一个 pr，由仓库主人进行审核，决定是否合并到仓库的主分支，这样就完成了一次协同开发</li><li><strong>README.md</strong>：文档</li><li><strong>.gitignore</strong>：忽略文件</li><li><strong>explore 部分（精华部分）</strong></li><li><strong>license</strong>：权限证书</li><li><strong>releases</strong>：发布的版本，直接下载使用</li><li><strong>projects</strong>：相当于项目开发计划版</li><li><strong>insights</strong>：项目仓库相关的数据界面</li></ul><h2 id="二、搜索技巧" tabindex="-1">二、搜索技巧 <a class="header-anchor" href="#二、搜索技巧" aria-label="Permalink to &quot;二、搜索技巧&quot;">​</a></h2><ul><li><p>高级搜索：随意搜索一个内容，在搜索结果的左下角有一个 <strong>advanced search</strong> 选项，这里可以对搜索附加筛选条件，使得搜索结果更加准确</p></li><li><p>搜索技巧汇总：</p><ul><li>找百科大全：<code>awesome xxx</code></li><li>找例子：<code>xxx sample</code></li><li>找空项目架子：<code>xxx starter</code> / <code>xxx boilerplate</code></li><li>找教程：<code>xxx tutorial</code></li></ul></li></ul><h2 id="三、技巧拓展-补充" tabindex="-1">三、技巧拓展/补充 <a class="header-anchor" href="#三、技巧拓展-补充" aria-label="Permalink to &quot;三、技巧拓展/补充&quot;">​</a></h2><ol><li><p>按下 <code>t</code> 键，对仓库的文件进行搜索，实现快速跳转，避免反复查找</p></li><li><p>按下 <code>l</code> 键，可以快速跳转到指定行号的代码</p></li><li><p>按下 <code>b</code> 键，跳转到 blame 界面，查看文件的修改记录</p></li><li><p>在仓库详情页按下<code>句号键</code>，使用网页版 vscode 打开项目，实现在线阅读</p></li><li><p>在线运行项目，在项目地址前加上 <code>gitpod.io/#/</code> 前缀</p><ul><li>会自动识别项目类型并安装依赖包，里面预装了如 python，java，go 等各种环境</li><li>可以在控制台输入命令运行项目，并直接在网页查看项目运行效果</li><li>还可以一键构建 docker 镜像</li></ul></li></ol><h2 id="四、资源整合" tabindex="-1">四、资源整合 <a class="header-anchor" href="#四、资源整合" aria-label="Permalink to &quot;四、资源整合&quot;">​</a></h2><h3 id="官方文档篇-tutorial" tabindex="-1">官方文档篇（tutorial） <a class="header-anchor" href="#官方文档篇-tutorial" aria-label="Permalink to &quot;官方文档篇（tutorial）&quot;">​</a></h3><blockquote><p>官方使用教程包含了所有内容，这里不再赘述，自行查看下方的官方使用教程文档，以下只列举一些相对重要的内容</p></blockquote><ul><li><a href="https://docs.github.com/zh" target="_blank" rel="noreferrer">Github 使用教程（中文版）</a></li><li><a href="https://docs.github.com/zh/search-github" target="_blank" rel="noreferrer">Search 的使用教程</a></li></ul><h3 id="找开源项目" tabindex="-1">找开源项目 <a class="header-anchor" href="#找开源项目" aria-label="Permalink to &quot;找开源项目&quot;">​</a></h3><ol><li><p><a href="https://hellogithub.com/" target="_blank" rel="noreferrer">Hello GitHub</a></p><ul><li>一个中文社区，集成了一些有意思的项目，点击链接即可跳转到项目仓库</li></ul></li><li><p><a href="https://gitstar-ranking.com/" target="_blank" rel="noreferrer">查看热门仓库等其他排名</a></p></li><li><p><a href="https://www.libhunt.com/" target="_blank" rel="noreferrer">LibHunt</a></p><ul><li>一个开源项目分类网站，可以说是无敌的存在</li><li><a href="https://blog.csdn.net/LANNY8588/article/details/115754015" target="_blank" rel="noreferrer">LibHunt 使用教程</a></li></ul></li><li><p><a href="https://searchcode.com/" target="_blank" rel="noreferrer">searchcode</a></p><ul><li>从全网根据 == 代码片段搜索==，并且可以选择平台选择语言进行过滤，通过搜索出来的代码片段跳转到仓库</li></ul></li><li><p><a href="https://unbug.github.io/codelf/" target="_blank" rel="noreferrer">codelf</a></p><ul><li>变量名命名工具</li><li><a href="https://blog.csdn.net/ShIcily/article/details/121904713" target="_blank" rel="noreferrer">使用教程</a></li></ul></li><li><p><a href="https://github.com/trending" target="_blank" rel="noreferrer">Github Trending</a></p></li><li><p><a href="https://github.com/geekxh/hello-algorithm" target="_blank" rel="noreferrer">图解算法题典</a></p></li></ol>',13))])}const q=i(d,[["render",p]]);export{k as __pageData,q as default};
